questionvariables.text:
/* pdec: exact decimal display of a value with at most 4 decimal places */
pdec(v) := if integerp(v) then v elseif integerp(10*v) then dispdp(float(v),1) elseif integerp(100*v) then dispdp(float(v),2) elseif integerp(1000*v) then dispdp(float(v),3) else dispdp(float(v),4);
/* Design: classify pattern, one response tree per table; fixed category order [no1, yes, no2]. Bank [values, fraction display flag, category], curated. Source: original. */
BK: [[[2/10,5/10,3/10],0,"yes"],[[1/4,1/2,1/8,1/8],1,"yes"],[[35/100,0,45/100,2/10],0,"yes"],[[1/3,1/6,1/2],1,"yes"],
     [[3/10,4/10,2/10],0,"no1"],[[25/100,25/100,35/100,25/100],0,"no1"],[[1/2,1/3,1/4],1,"no1"],[[1/10,6/10,2/10,2/10],0,"no1"],
     [[6/10,-1/10,5/10],0,"no2"],[[12/10,-3/10,1/10],0,"no2"],[[5/10,7/10,-2/10],0,"no2"],[[3/4,1/2,-1/4],1,"no2"]];
TR: [[1,5,9],[10,2,3],[6,11,7],[4,12,8],[9,7,3],[8,1,10],[2,6,4],[12,11,1],[5,4,11],[3,8,12]];
ix: 1+rand(10);
i1: TR[ix][1]; i2: TR[ix][2]; i3: TR[ix][3];
v1: BK[i1][1]; v2: BK[i2][1]; v3: BK[i3][1];
f1: BK[i1][2]; f2: BK[i2][2]; f3: BK[i3][2];
c1: BK[i1][3]; c2: BK[i2][3]; c3: BK[i3][3];
mkopt(c) := [["no1", is(c="no1"), "No: the probabilities do not add up to 1."], ["yes", is(c="yes"), "Yes, it is a probability distribution."], ["no2", is(c="no2"), "No: a probability is less than 0 or more than 1."]];
o1: mkopt(c1); o2: mkopt(c2); o3: mkopt(c3);
/* first wrong key in the order [no1, yes, no2] and the remaining one */
wa(c) := if c="no1" then "yes" else "no1";
wb(c) := if c="no2" then "yes" else "no2";
w11: wa(c1); w12: wb(c1); w21: wa(c2); w22: wb(c2); w31: wa(c3); w32: wb(c3);
tot1: apply("+",v1); tot2: apply("+",v2); tot3: apply("+",v3);
cn1: if c1="yes" then 1 elseif c1="no1" then 2 else 3; cn2: if c2="yes" then 1 elseif c2="no1" then 2 else 3; cn3: if c3="yes" then 1 elseif c3="no1" then 2 else 3;
bad(v) := first(sublist(v, lambda([u], u<0 or u>1)));
bd1: if c1="no2" then bad(v1) else 0; bd2: if c2="no2" then bad(v2) else 0; bd3: if c3="no2" then bad(v3) else 0;
